export function Messages({
  orgName = "Jumpstart Connect",
  pageLabel = "Communication",
}) {
  const currentUser = useMemo(() => getCurrentUser(), []);
  const currentUserId = currentUser?.id ?? null;

  const [directMessages, setDirectMessages] = useState([]);
  const [availableContacts, setAvailableContacts] = useState([]);
  const [activeChannelId, setActiveChannelId] = useState(null);
  const [conversationMessages, setConversationMessages] = useState([]);
  const [loadingInbox, setLoadingInbox] = useState(true);
  const [loadingConversation, setLoadingConversation] = useState(false);
  const [error, setError] = useState(null);

  const [draft, setDraft] = useState("");
  const [attachments, setAttachments] = useState([]);
  const [shareAttachment, setShareAttachment] = useState(null);
  const [shareRecipientId, setShareRecipientId] = useState(null);
  const [shareNote, setShareNote] = useState("");
  const [shareSubmitting, setShareSubmitting] = useState(false);
  const [dmsExpanded, setDmsExpanded] = useState(true);
  const [channelSearch, setChannelSearch] = useState("");
  const [isTyping, setIsTyping] = useState(false);
  const bottomRef = useRef(null);
  const inputRef = useRef(null);

  // ── Build the conversation list from the inbox ───────────────────────────
  const loadInbox = useCallback(async () => {
    if (!currentUserId) {
      setError("No logged-in user found.");
      setLoadingInbox(false);
      return;
    }

    try {
      setLoadingInbox(true);
      setError(null);

      const data = await messageApi.getThreads(currentUserId);
      const rawMessages = data?.inbox || [];

      // Group messages by the "other" participant in the conversation
      const conversationsByPartner = new Map();

      rawMessages.forEach((m) => {
        const isOutgoing = m.sender_id === currentUserId;
        const partnerId = isOutgoing ? m.receiver_id : m.sender_id;
        const partnerName = isOutgoing ? m.receiver_name : m.sender_name;

        const existing = conversationsByPartner.get(partnerId);
        const entry = {
          id: partnerId,
          name: partnerName || "Unknown",
          lastMessage: m.message,
          lastTimestamp: m.timestamp,
          unread: 0,
        };

        if (!existing || new Date(m.timestamp) > new Date(existing.lastTimestamp)) {
          conversationsByPartner.set(partnerId, entry);
        }
      });

      const conversations = Array.from(conversationsByPartner.values()).sort(
        (a, b) => new Date(b.lastTimestamp) - new Date(a.lastTimestamp)
      );

      setDirectMessages(conversations);

      setActiveChannelId((prev) => {
        if (prev) return prev;
        return conversations.length > 0 ? conversations[0].id : null;
      });
    } catch (err) {
      console.error("Failed to load inbox:", err);
      setError(err.message);
    } finally {
      setLoadingInbox(false);
    }
  }, [currentUserId]);

  const loadContacts = useCallback(async () => {
    if (!currentUserId) {
      setAvailableContacts([]);
      return;
    }

    try {
      const data = await messageApi.getContacts(currentUserId);
      const contacts = Array.isArray(data?.contacts) ? data.contacts : [];
      setAvailableContacts(contacts);
    } catch (err) {
      console.error("Failed to load contacts:", err);
      setAvailableContacts([]);
    }
  }, [currentUserId]);

  useEffect(() => {
    loadInbox();
    loadContacts();
  }, [loadInbox, loadContacts]);

  const sidebarContacts = useMemo(() => {
    const existingIds = new Set(directMessages.map((conversation) => conversation.id));

    return (availableContacts || [])
      .filter((contact) => !existingIds.has(contact.id))
      .map((contact) => ({
        id: contact.id,
        name: contact.name || contact.email || "Unknown",
        email: contact.email,
        department: contact.department,
        role: contact.role,
        lastMessage: "",
        lastTimestamp: null,
        unread: 0,
        isContact: true,
      }));
  }, [availableContacts, directMessages]);

  const sidebarChannels = useMemo(() => {
    return [...directMessages, ...sidebarContacts].sort((a, b) => {
      if (!a.lastTimestamp && !b.lastTimestamp) return 0;
      if (!a.lastTimestamp) return 1;
      if (!b.lastTimestamp) return -1;
      return new Date(b.lastTimestamp) - new Date(a.lastTimestamp);
    });
  }, [directMessages, sidebarContacts]);

  const shareTargets = useMemo(() => {
    const unique = new Map();
    sidebarChannels.forEach((target) => {
      if (!unique.has(target.id)) unique.set(target.id, target);
    });
    return Array.from(unique.values());
  }, [sidebarChannels]);

  useEffect(() => {
    setActiveChannelId((prev) => {
      if (prev && sidebarChannels.some((channel) => channel.id === prev)) {
        return prev;
      }
      return sidebarChannels[0]?.id ?? null;
    });
  }, [sidebarChannels]);

  // ── Load the open conversation's messages ─────────────────────────────────
  const loadConversation = useCallback(async (partnerId) => {
    if (!currentUserId || !partnerId) {
      setConversationMessages([]);
      return;
    }

    try {
      setLoadingConversation(true);
      const data = await messageApi.getThread(currentUserId, partnerId);
      console.log("getThread response:", data);

      // The backend may return a plain array, or wrap it in an object
      // (e.g. { conversation: [...] } or { messages: [...] }) — handle both.
      const rawMessages = Array.isArray(data)
        ? data
        : Array.isArray(data?.conversation)
        ? data.conversation
        : Array.isArray(data?.messages)
        ? data.messages
        : Array.isArray(data?.results)
        ? data.results
        : [];

      const mapped = rawMessages
        .slice()
        .sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp))
        .map((m) => ({
          id: m.id,
          author: m.sender_id === currentUserId ? "You" : m.sender_name,
          text: m.message || "",
          time: formatTime(m.timestamp),
          attachments: Array.isArray(m.attachments)
            ? m.attachments.map((att) => ({
                id: att.id,
                name: att.name,
                size: typeof att.size === "number" ? `${(att.size / 1024).toFixed(1)} KB` : att.size,
                type: att.type,
                mimeType: att.mimeType,
                url: att.url,
              }))
            : [],
        }));

      setConversationMessages(mapped);
    } catch (err) {
      console.error("Failed to load conversation:", err);
      setError(err.message);
      setConversationMessages([]);
    } finally {
      setLoadingConversation(false);
    }
  }, [currentUserId, activeChannelId]);

  useEffect(() => {
    if (activeChannelId) {
      loadConversation(activeChannelId);
    }
  }, [activeChannelId, loadConversation]);

  // Scroll to bottom when messages change
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [conversationMessages.length]);

  const filteredDMs = useMemo(() => {
    if (!channelSearch.trim()) return directMessages;
    const q = channelSearch.toLowerCase();
    return directMessages.filter((d) => d.name.toLowerCase().includes(q));
  }, [directMessages, channelSearch]);

  const filteredContacts = useMemo(() => {
    if (!channelSearch.trim()) return sidebarContacts;
    const q = channelSearch.toLowerCase();
    return sidebarContacts.filter((contact) => contact.name.toLowerCase().includes(q));
  }, [sidebarContacts, channelSearch]);

  const selectedChannel = useMemo(
    () => sidebarChannels.find((channel) => channel.id === activeChannelId) ?? null,
    [sidebarChannels, activeChannelId]
  );

  // ── Handlers ──────────────────────────────────────────────────────────────
  const handleChannelSelect = useCallback((id) => {
    setActiveChannelId(id);
  }, []);

  const handleOpenShareAttachment = (attachment) => {
    setShareAttachment(attachment);
    setShareRecipientId(shareTargets[0]?.id || null);
    setShareNote("");
  };

  const handleCloseShareAttachment = () => {
    setShareAttachment(null);
    setShareRecipientId(null);
    setShareNote("");
    setShareSubmitting(false);
  };

  const handleConfirmShareAttachment = async () => {
    if (!shareAttachment || !shareRecipientId || !currentUserId) return;

    try {
      setShareSubmitting(true);
      setError(null);

      await messageApi.shareAttachment({
        senderId: currentUserId,
        receiverId: shareRecipientId,
        attachmentId: shareAttachment.id,
        message: shareNote.trim(),
      });

      if (shareRecipientId === activeChannelId) {
        await loadConversation(activeChannelId);
      }
      await loadInbox();
      await loadContacts();
      handleCloseShareAttachment();
    } catch (err) {
      console.error("Failed to share attachment:", err);
      setError(err.message);
      setShareSubmitting(false);
    }
  };

  const handleFileChange = (event) => {
    const files = Array.from(event.target.files || []);
    if (!files.length) return;
    setAttachments((existing) => [...existing, ...files]);
    event.target.value = "";
  };

  const handleRemoveAttachment = (name) => {
    setAttachments((prev) => prev.filter((f) => f.name !== name));
  };

  const handleSendMessage = async () => {
    const text = draft.trim();
    if (!selectedChannel || !currentUserId || (!text && attachments.length === 0)) return;

    try {
      await messageApi.sendMessage({
        senderId: currentUserId,
        receiverId: selectedChannel.id,
        message: text,
        attachments,
      });

      setDraft("");
      setAttachments([]);
      setIsTyping(false);
      inputRef.current?.focus();

      await loadConversation(selectedChannel.id);
      await loadInbox();
      await loadContacts();
    } catch (err) {
      console.error("Failed to send message:", err);
      setError(err.message);
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const handleReact = (msgId, emoji) => {
    console.log("React to message", msgId, emoji);
  };

  if (loadingInbox && directMessages.length === 0) {
    return (
      <div className="flex h-[calc(100vh-9rem)] bg-[#0D0D0D] rounded-2xl border border-[#1E1E1E] overflow-hidden items-center justify-center">
        <div className="flex flex-col items-center gap-4 text-center px-8">
          <div className="w-12 h-12 rounded-2xl bg-[#1A1A1A] border border-[#222] flex items-center justify-center">
            <MessageSquare size={22} className="text-[#333]" />
          </div>
          <p className="text-sm text-white font-medium">Loading conversations...</p>
        </div>
      </div>
    );
  }

  if (!selectedChannel) {
    return (
      <div className="flex h-[calc(100vh-9rem)] bg-[#0D0D0D] rounded-2xl border border-[#1E1E1E] overflow-hidden items-center justify-center">
        <div className="flex flex-col items-center gap-4 text-center px-8">
          <div className="w-12 h-12 rounded-2xl bg-[#1A1A1A] border border-[#222] flex items-center justify-center">
            <MessageSquare size={22} className="text-[#333]" />
          </div>
          <p className="text-sm text-white font-medium">No conversations available</p>
          <p className="text-xs text-[#444]">
            {error ? error : "There are currently no messages to display."}
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-[calc(100vh-9rem)]">
      {/* Breadcrumb bar */}
      <div className="flex items-center justify-between mb-3 px-1">
        <div className="flex items-center gap-1.5 text-sm">
          <span className="text-[#555]">{orgName}</span>
          <ChevronRight size={13} className="text-[#444]" />
          <span className="text-white font-semibold">{pageLabel}</span>
        </div>
      </div>

      <div className="flex flex-1 bg-[#0D0D0D] rounded-2xl border border-[#1E1E1E] overflow-hidden">
        {/* ── Left panel ── */}
        <div className="w-60 flex-shrink-0 border-r border-[#1E1E1E] flex flex-col bg-[#111111]">
          {/* Search */}
          <div className="p-3 border-b border-[#1A1A1A]">
            <div className="relative">
              <Search size={12} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-[#444]" />
              <input
                type="text"
                value={channelSearch}
                onChange={(e) => setChannelSearch(e.target.value)}
                placeholder="Find conversations..."
                className="w-full bg-[#1A1A1A] border border-[#222] text-white pl-7 pr-3 py-1.5 rounded-lg text-xs focus:outline-none focus:border-[#F5C518]/30 transition-all"
              />
            </div>
          </div>

          <div className="flex-1 overflow-y-auto py-2 px-2">
            {/* Direct messages */}
            <button
              onClick={() => setDmsExpanded(!dmsExpanded)}
              className="w-full flex items-center gap-1.5 px-1 py-1 text-[10px] font-semibold text-[#444] uppercase tracking-wider hover:text-[#666] transition-colors"
            >
              {dmsExpanded ? <ChevronDown size={11} /> : <ChevronRight size={11} />}
              Direct Messages
            </button>
            {dmsExpanded && (
              <div className="space-y-0.5 mt-1">
                {filteredDMs.length > 0 && (
                  <>
                    <div className="px-1 py-1 text-[10px] font-semibold uppercase tracking-wider text-[#444]">
                      Conversations
                    </div>
                    {filteredDMs.map((dm) => (
                      <DMItem
                        key={dm.id}
                        dm={dm}
                        isActive={dm.id === selectedChannel?.id}
                        onSelect={handleChannelSelect}
                      />
                    ))}
                  </>
                )}

                {filteredContacts.length > 0 && (
                  <>
                    <div className="px-1 py-1 mt-2 text-[10px] font-semibold uppercase tracking-wider text-[#444]">
                      Available people
                    </div>
                    {filteredContacts.map((contact) => (
                      <DMItem
                        key={contact.id}
                        dm={{ ...contact, unread: 0 }}
                        isActive={contact.id === selectedChannel?.id}
                        onSelect={handleChannelSelect}
                      />
                    ))}
                  </>
                )}
              </div>
            )}
          </div>
        </div>

        {/* ── Main area ── */}
        <div className="flex-1 flex flex-col min-w-0">
          {/* Channel header */}
          <div className="h-12 border-b border-[#1E1E1E] flex items-center justify-between px-4 flex-shrink-0 bg-[#111111]">
            <div className="flex items-center gap-2 min-w-0">
              <Hash size={15} className="text-[#666] flex-shrink-0" />
              <span className="text-sm font-semibold text-white truncate">{selectedChannel.name}</span>
            </div>
            <div className="flex items-center gap-1 flex-shrink-0">
              <button className="w-7 h-7 rounded-lg flex items-center justify-center text-[#444] hover:text-white hover:bg-[#1A1A1A] transition-all">
                <Phone size={14} />
              </button>
              <button className="w-7 h-7 rounded-lg flex items-center justify-center text-[#444] hover:text-white hover:bg-[#1A1A1A] transition-all">
                <Video size={14} />
              </button>
              <button className="w-7 h-7 rounded-lg flex items-center justify-center text-[#444] hover:text-white hover:bg-[#1A1A1A] transition-all">
                <Info size={14} />
              </button>
            </div>
          </div>

          {/* Messages */}
          <div className="flex-1 overflow-y-auto py-2 space-y-0.5 bg-[#0D0D0D]">
            {loadingConversation && conversationMessages.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-full gap-3 text-center px-8">
                <div className="w-12 h-12 rounded-2xl bg-[#1A1A1A] border border-[#222] flex items-center justify-center">
                  <MessageSquare size={22} className="text-[#333]" />
                </div>
                <p className="text-sm text-white font-medium">Loading messages...</p>
              </div>
            ) : conversationMessages.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-full gap-3 text-center px-8">
                <div className="w-12 h-12 rounded-2xl bg-[#1A1A1A] border border-[#222] flex items-center justify-center">
                  <MessageSquare size={22} className="text-[#333]" />
                </div>
                <p className="text-sm text-white font-medium">No messages yet</p>
                <p className="text-xs text-[#444]">Start the conversation with {selectedChannel.name}</p>
              </div>
            ) : (
              conversationMessages.map((msg) => (
                <MessageRow key={msg.id} msg={msg} onReact={handleReact} onShare={handleOpenShareAttachment} />
              ))
            )}

            {isTyping && (
              <div className="flex items-center gap-3 px-4 py-1">
                <div className="w-8 h-8 rounded-full bg-[#2A2A2A] flex items-center justify-center text-[10px] text-[#888]">
                  {selectedChannel.name?.charAt(0) || "?"}
                </div>
                <div className="flex items-center gap-1 bg-[#1A1A1A] rounded-xl px-3 py-2">
                  {[0, 1, 2].map((i) => (
                    <span
                      key={i}
                      className="w-1.5 h-1.5 rounded-full bg-[#444] animate-bounce"
                      style={{ animationDelay: `${i * 0.15}s` }}
                    />
                  ))}
                </div>
                <span className="text-[10px] text-[#333]">typing...</span>
              </div>
            )}
            <div ref={bottomRef} />
          </div>

          {/* Input */}
          <div className="p-3 border-t border-[#1E1E1E] flex-shrink-0 bg-[#111111]">
            <div className="bg-[#1A1A1A] border border-[#2A2A2A] rounded-xl overflow-hidden focus-within:border-[#F5C518]/30 transition-all">
              <textarea
                ref={inputRef}
                value={draft}
                onChange={(e) => setDraft(e.target.value)}
                onKeyDown={handleKeyDown}
                placeholder={`Message ${selectedChannel.name}...`}
                rows={1}
                className="w-full bg-transparent px-4 pt-3 pb-1 text-sm text-white placeholder-[#444] focus:outline-none resize-none"
                style={{ minHeight: "44px", maxHeight: "120px" }}
              />

              {/* Attachments preview */}
              {attachments.length > 0 && (
                <div className="px-3 pb-2 space-y-1.5">
                  {attachments.map((file) => {
                    const ext = file.name.split(".").pop()?.toLowerCase() || "pdf";
                    const typeMap = { png: "image", jpg: "image", jpeg: "image", gif: "image", webp: "image" };
                    const attType = typeMap[ext] || "pdf";
                    const s = ATTACH_ICONS[attType] || ATTACH_ICONS.pdf;
                    return (
                      <div key={file.name} className="flex items-center justify-between gap-3 bg-[#111] border border-[#2A2A2A] rounded-lg px-3 py-2">
                        <div className="flex items-center gap-2 min-w-0">
                          <FileText size={14} className={s.color} />
                          <span className="text-xs text-[#888] truncate">{file.name}</span>
                          <span className="text-[10px] text-[#444]">({(file.size / 1024).toFixed(1)} KB)</span>
                        </div>
                        <button
                          type="button"
                          onClick={() => handleRemoveAttachment(file.name)}
                          className="text-[#444] hover:text-white transition-colors flex-shrink-0"
                        >
                          <X size={14} />
                        </button>
                      </div>
                    );
                  })}
                </div>
              )}

              <div className="flex items-center justify-between px-3 pb-2">
                <div className="flex items-center gap-1">
                  {[
                    { icon: Smile, label: "Emoji" },
                    { icon: Paperclip, label: "Attach", isLabel: true },
                    { icon: AtSign, label: "Mention" },
                    { icon: Mic, label: "Voice note" },
                  ].map(({ icon: Icon, label, isLabel }) =>
                    isLabel ? (
                      <label
                        key={label}
                        htmlFor="chat-file-input"
                        title={label}
                        className="w-7 h-7 rounded-lg flex items-center justify-center text-[#444] hover:text-white hover:bg-[#2A2A2A] transition-all cursor-pointer"
                      >
                        <Icon size={14} />
                      </label>
                    ) : (
                      <button
                        key={label}
                        title={label}
                        type="button"
                        className="w-7 h-7 rounded-lg flex items-center justify-center text-[#444] hover:text-white hover:bg-[#2A2A2A] transition-all"
                      >
                        <Icon size={14} />
                      </button>
                    )
                  )}

                  <input
                    id="chat-file-input"
                    type="file"
                    className="hidden"
                    multiple
                    onChange={handleFileChange}
                  />
                </div>
                <button
                  onClick={handleSendMessage}
                  disabled={!draft.trim() && attachments.length === 0}
                  className="flex items-center gap-1.5 bg-primary text-primary-foreground px-3 py-1.5 rounded-lg text-xs font-semibold hover:opacity-90 transition-all disabled:opacity-30 disabled:cursor-not-allowed"
                >
                  <Send size={12} /> Send
                </button>
              </div>
            </div>
            <p className="text-[10px] text-[#333] mt-1.5 px-1">
              Press <kbd className="bg-[#1A1A1A] border border-[#2A2A2A] px-1 py-0.5 rounded text-[9px]">Enter</kbd> to send ·{" "}
              <kbd className="bg-[#1A1A1A] border border-[#2A2A2A] px-1 py-0.5 rounded text-[9px]">Shift+Enter</kbd> for new line
            </p>
          </div>
        </div>
      </div>

      {shareAttachment && (
        <ShareAttachmentModal
          attachment={shareAttachment}
          targets={shareTargets}
          selectedTargetId={shareRecipientId}
          onSelectTarget={setShareRecipientId}
          note={shareNote}
          onNoteChange={setShareNote}
          onClose={handleCloseShareAttachment}
          onSubmit={handleConfirmShareAttachment}
          submitting={shareSubmitting}
        />
      )}
    </div>
  );
}

import { useEffect, useState } from "react";
import { Search, Plus, MoreHorizontal, UserCheck, UserX, Mail, Download, Edit2, Trash2, Shield, ChevronDown, } from "lucide-react";
import { usersApi } from "../../services/usersApi";
import { departmentsApi } from "../../services/departmentsApi";
const ROLES = [
    "All Roles",
    "System Administrator",
    "Organization Administrator",
    "Department Manager",
    "Team Leader",
    "Employee",
    "Intern",
    "Volunteer",
    "Viewer",
];
const DEPTS = ["All Departments", "System Admin", "Management", "Human Resources", "Monitoring & Evaluation", "Project Management", "Planning & Development", "Technology", "Marketing", "clean Energy", "Board Members"];
const STATUSES = ["All", "Active", "Inactive", "Pending"];
const STATUS_STYLE = {
    active: "bg-green-500/10 text-green-400 border-green-500/20",
    inactive: "bg-[#2A2A2A] text-[#666] border-[#333]",
    pending: "bg-[#F5C518]/10 text-[#F5C518] border-[#F5C518]/20",
};
const ROLE_COLORS = {
    "System Admin": "text-red-400",
    "Administrator": "text-orange-400",
    "Board Owner": "text-[#F5C518]",
    "Employee": "text-blue-400",
    "Viewer": "text-[#666]",
};
export function UsersAccess() {
    const [search, setSearch] = useState("");
    const [roleFilter, setRoleFilter] = useState("All Roles");
    const [deptFilter, setDeptFilter] = useState("All Departments");
    const [statusFilter, setStatusFilter] = useState("All");
    const [openMenu, setOpenMenu] = useState(null);
    const [showInviteModal, setShowInviteModal] = useState(false);
    const [inviteEmail, setInviteEmail] = useState("");
    const [inviteDept, setInviteDept] = useState("");
const [departments, setDepartments] = useState([]);
    const [users, setUsers] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    const loadDepartments = async () => {
    try {
        const data = await departmentsApi.list();

        setDepartments(data);

        if (data.length > 0) {
            setInviteDept(data[0].name);
        }
    } catch (err) {
        console.error("Failed to load departments", err);
    }
};

const loadUsers = async () => {
    try {
        setLoading(true);

        
    
    const data = await usersApi.list();

    const mapped = data.map((u) => ({
      id: u.id,
      name: `${u.first_name} ${u.last_name}`,
      email: u.email,
      role: u.role || "Employee",
      dept: u.department || "",
      status: u.is_active ? "active" : "inactive",
      joined: new Date(u.created_at).toLocaleDateString(),
      last: "-",
      twofa: false,
    }));

    setUsers(mapped);
  } catch (err) {
    console.error(err);
    setError(err.message);
  } finally {
    setLoading(false);
  }
};

const handleCreateUser = async () => {
  try {
    if (!inviteEmail.trim()) {
      alert("Please enter an email address");
      return;
    }

    const username = inviteEmail.split("@")[0];
    const parts = username.split(".");

    const firstName =
      parts[0]?.charAt(0).toUpperCase() +
      parts[0]?.slice(1);

    const lastName =
      parts[1]?.charAt(0).toUpperCase() +
      parts[1]?.slice(1);

    await usersApi.create({
      email: inviteEmail,
      first_name: firstName || "User",
      last_name: lastName || "",
      department: inviteDept,
      role: "Employee",
    });

    await loadUsers();

    setInviteEmail("");
    setInviteDept("Technology");

    setShowInviteModal(false);

    alert("User created successfully");
  } catch (err) {
    console.error(err);

    alert(
      err?.response?.data?.error ||
      err?.response?.data?.details ||
      err.message
    );
  }
};

useEffect(() => {
    loadUsers();
    loadDepartments();
}, []);
    
    const filtered = users.filter((u) => {
        const matchSearch = u.name.toLowerCase().includes(search.toLowerCase()) || u.email.toLowerCase().includes(search.toLowerCase());
        const matchRole = roleFilter === "All Roles" || u.role === roleFilter;
        const matchDept = deptFilter === "All Departments" || u.dept === deptFilter;
        const matchStatus = statusFilter === "All" || u.status === statusFilter;
        return matchSearch && matchRole && matchDept && matchStatus;
    });
    return (<div className="space-y-5">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-xl font-bold text-black">Users & Access</h1>
          <p className="text-[#F5C518] text-xs mt-0.5">Manage platform users, roles, and access permissions</p>
        </div>
        <button onClick={() => setShowInviteModal(true)} className="flex items-center gap-2 bg-[#F5C518] text-black px-4 py-2 rounded-xl text-sm font-semibold hover:bg-[#E6B800] transition-all">
          <Plus size={15}/> Add Member
        </button>
      </div>

      {/* Stats row */}
      <div className="grid grid-cols-4 gap-4">
        {loading ? (<div>Loading users…</div>) : ([
            { label: "Total Users", value: users.length, color: "#F5C518" },
            { label: "Active", value: users.filter((u) => u.status === "active").length, color: "#4ADE80" },
            { label: "Pending", value: users.filter((u) => u.status === "pending").length, color: "#FBBF24" },
            { label: "2FA Enabled", value: users.filter((u) => u.twofa).length, color: "#60A5FA" },
        ].map((s) => (<div key={s.label} className="bg-[#111111] border border-[#1E1E1E] rounded-2xl p-4">
            <div className="text-2xl font-bold mb-0.5" style={{ color: s.color }}>{s.value}</div>
            <div className="text-[#444] text-xs">{s.label}</div>
          </div>)))}
      </div>

      {/* Filters */}
      <div className="bg-[#111111] border border-[#1E1E1E] rounded-2xl p-4 flex flex-wrap gap-3 items-center">
        <div className="relative flex-1 min-w-48">
          <Search size={13} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#444]"/>
          <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search by name or email..." className="w-full bg-[#0D0D0D] border border-[#1E1E1E] text-white pl-9 pr-4 py-2 rounded-xl text-xs placeholder-[#333] focus:outline-none focus:border-[#F5C518]/40 transition-all"/>
        </div>
        {[
            { label: "Role", value: roleFilter, options: ROLES, set: setRoleFilter },
            { label: "Dept", value: deptFilter, options: DEPTS, set: setDeptFilter },
            { label: "Status", value: statusFilter, options: STATUSES, set: setStatusFilter },
        ].map((f) => (<div key={f.label} className="relative">
            <select value={f.value} onChange={(e) => f.set(e.target.value)} className="appearance-none bg-[#0D0D0D] border border-[#1E1E1E] text-[#888] text-xs px-3 py-2 pr-8 rounded-xl focus:outline-none focus:border-[#F5C518]/40 transition-all cursor-pointer">
              {f.options.map((o) => <option key={o}>{o}</option>)}
            </select>
            <ChevronDown size={11} className="absolute right-2 top-1/2 -translate-y-1/2 text-[#444] pointer-events-none"/>
          </div>))}
        <button className="flex items-center gap-1.5 text-[#555] text-xs border border-[#1E1E1E] bg-[#0D0D0D] px-3 py-2 rounded-xl hover:border-[#2A2A2A] hover:text-white transition-all ml-auto">
          <Download size={13}/> Export
        </button>
      </div>

      {/* Table */}
      <div className="bg-[#111111] border border-[#1E1E1E] rounded-2xl overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-xs">
            <thead>
              <tr className="border-b border-[#1A1A1A]">
                {["User", "Role", "Department", "Status", "2FA", "Last Active", "Joined", ""].map((h) => (<th key={h} className="text-left text-[#444] font-medium px-4 py-3">{h}</th>))}
              </tr>
            </thead>
            <tbody>
              {filtered.map((user) => (<tr key={user.id} className="border-b border-[#0D0D0D] hover:bg-[#141414] transition-all group">
                  <td className="px-4 py-3">
                    <div className="flex items-center gap-3">
                      <div className="w-7 h-7 rounded-full bg-[#F5C518]/15 flex items-center justify-center flex-shrink-0">
                        <span className="text-[#F5C518] text-[9px] font-bold">{user.name.split(" ").map((n) => n[0]).join("")}</span>
                      </div>
                      <div>
                        <div className="text-white font-medium">{user.name}</div>
                        <div className="text-[#444] text-[10px]">{user.email}</div>
                      </div>
                    </div>
                  </td>
                  <td className="px-4 py-3">
                    <span className={`font-medium ${ROLE_COLORS[user.role] || "text-[#888]"}`}>{user.role}</span>
                  </td>
                  <td className="px-4 py-3 text-[#888]">{user.dept}</td>
                  <td className="px-4 py-3">
                    <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs border ${STATUS_STYLE[user.status]}`}>
                      {user.status}
                    </span>
                  </td>
                  <td className="px-4 py-3">
                    {user.twofa ? (<Shield size={13} className="text-green-400"/>) : (<Shield size={13} className="text-[#333]"/>)}
                  </td>
                  <td className="px-4 py-3 text-[#555]">{user.last}</td>
                  <td className="px-4 py-3 text-[#555]">{user.joined}</td>
                  <td className="px-4 py-3">
                    <div className="relative">
                      <button onClick={() => setOpenMenu(openMenu === user.id ? null : user.id)} className="opacity-0 group-hover:opacity-100 transition-opacity text-[#444] hover:text-white p-1">
                        <MoreHorizontal size={14}/>
                      </button>
                      {openMenu === user.id && (<div className="absolute right-0 top-7 z-20 bg-[#1A1A1A] border border-[#2A2A2A] rounded-xl p-1 w-44 shadow-xl">
                          {[
                    { icon: Edit2, label: "Edit User", color: "text-white" },
                    { icon: Mail, label: "Send Reset Link", color: "text-white" },
                    { icon: user.status === "active" ? UserX : UserCheck, label: user.status === "active" ? "Deactivate" : "Activate", color: user.status === "active" ? "text-orange-400" : "text-green-400" },
                    { icon: Trash2, label: "Remove User", color: "text-red-400" },
                ].map((action) => (<button key={action.label} onClick={() => setOpenMenu(null)} className={`w-full flex items-center gap-2.5 px-3 py-2 rounded-lg text-xs hover:bg-[#2A2A2A] transition-all ${action.color}`}>
                              <action.icon size={13}/> {action.label}
                            </button>))}
                        </div>)}
                    </div>
                  </td>
                </tr>))}
            </tbody>
          </table>
          {filtered.length === 0 && (<div className="text-center text-[#444] py-10 text-sm">No users match your filters.</div>)}
        </div>
      </div>

      {/* Invite Modal */}
      {showInviteModal && (<div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm">
          <div className="bg-[#111111] border border-[#2A2A2A] rounded-2xl p-6 w-full max-w-md mx-4 shadow-2xl">
            <h2 className="text-white font-semibold text-base mb-1">Invite New User</h2>
            <p className="text-[#444] text-xs mb-5">Only approved organisational email domains are permitted.</p>
            <div className="space-y-4">
              <div>
                <label className="text-xs text-[#888] block mb-1.5">Email Address</label>
                <input value={inviteEmail} onChange={(e) => setInviteEmail(e.target.value)} placeholder="user@jumpstartyourcareer.co.za" className="w-full bg-[#0D0D0D] border border-[#2A2A2A] text-white px-4 py-2.5 rounded-xl text-sm placeholder-[#333] focus:outline-none focus:border-[#F5C518]/50 transition-all"/>
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-xs text-[#888] block mb-1.5">Department</label>
                  <select value={inviteDept} onChange={(e) => setInviteDept(e.target.value)} className="w-full bg-[#0D0D0D] border border-[#2A2A2A] text-white px-3 py-2.5 rounded-xl text-sm focus:outline-none focus:border-[#F5C518]/50 transition-all">
                    {departments.map((dept) => (
    <option
        key={dept.id}
        value={dept.name}
    >
        {dept.name}
    </option>
))}
                  </select>
                </div>
              </div>
            </div>
            <div className="flex gap-3 mt-6">
              <button
  onClick={handleCreateUser}
  className="flex-1 bg-[#F5C518] text-black py-2.5 rounded-xl text-sm font-semibold hover:bg-[#E6B800] transition-all"
>
  Send Invite
</button>
            </div>
          </div>
        </div>)}
    </div>);
}

import { useState, useEffect, useCallback } from "react";
import { Plus, LayoutGrid, List, Users, Layers, MoreHorizontal, Search, Settings, Eye, Trash2, Lock, Loader2, ShieldCheck } from "lucide-react";
import { groupsApi } from "../../services/groupsApi";
import { WorkspaceEnvironment } from "./workspace/WorkspaceEnvironment";
const STATUS_STYLES = {
  active: "bg-green-500/10 text-green-400 border-green-500/20",
  restricted: "bg-orange-500/10 text-orange-400 border-orange-500/20",
  archived: "bg-[#2A2A2A] text-[#777] border-[#333]",
};

const DEPT_COLORS = ["#60A5FA", "#F5C518", "#F472B6", "#4ADE80", "#A78BFA", "#FB923C"];

function colorForDept(id) {
  return DEPT_COLORS[id % DEPT_COLORS.length];
}

export function Workspaces() {
  const currentUser =
  JSON.parse(localStorage.getItem("currentUser")) ||
  JSON.parse(localStorage.getItem("user"));

const userRole = currentUser?.role || "";
const userDepartment = currentUser?.department || "";

const canCreateWorkspace =
  userRole === "SuperAdmin" ||
  userRole === "System Administrator" ||
  userRole === "Organization Administrator";
    
  const [view, setView] = useState("grid");
  const [search, setSearch] = useState("");
  const [expanded, setExpanded] = useState(null);
  const [openMenu, setOpenMenu] = useState(null);

  const [workspaces, setWorkspaces] = useState([]);
  const [departments, setDepartments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const [showCreate, setShowCreate] = useState(false);
  const [creating, setCreating] = useState(false);
  const [newName, setNewName] = useState("");
  const [newType, setNewType] = useState("Department");
  const [newDepartment, setNewDepartment] = useState("");
  const [visibility, setVisibility] = useState("private");
  const [autoAssign, setAutoAssign] = useState(true);
  const [autoAdmin, setAutoAdmin] = useState(true);
const [selectedWorkspace, setSelectedWorkspace] = useState(null);

const openWorkspace = (workspace) => {
    setSelectedWorkspace(workspace);
};

const closeWorkspace = () => {
    setSelectedWorkspace(null);
};
  const loadData = useCallback(async () => {
  setLoading(true);
  setError(null);

  try {
    const currentUser =
    JSON.parse(localStorage.getItem("currentUser")) ||
    JSON.parse(localStorage.getItem("user"));
    if (!currentUser) {
      throw new Error("No logged-in user found");
    }

    const res = await groupsApi.list(currentUser.id);

    setWorkspaces(Array.isArray(res.groups) ? res.groups : []);
    setDepartments([]);
  } catch (err) {
    console.error("Failed to load workspaces:", err);
    setError("Couldn't load workspaces.");
  } finally {
    setLoading(false);
  }
}, []);


  useEffect(() => {
    loadData();
  }, [loadData]);

  useEffect(() => {
    if (departments.length && !newDepartment) {
      setNewDepartment(String(departments[0].id));
    }
  }, [departments, newDepartment]);

  const visibleWorkspaces = workspaces;

const filtered = visibleWorkspaces.filter((w) =>
  w.name?.toLowerCase().includes(search.toLowerCase()) ||
  w.owner_name?.toLowerCase().includes(search.toLowerCase()) ||
  w.department_name?.toLowerCase().includes(search.toLowerCase())
);

if (selectedWorkspace) {
    return (
        <WorkspaceEnvironment
            workspace={selectedWorkspace}
            messages={selectedWorkspace.messages || []}
            announcements={selectedWorkspace.announcements || []}
            members={selectedWorkspace.members || []}
            currentUser={currentUser}
            onBack={closeWorkspace}
        />
    );
}

  const resetCreateForm = () => {
    setNewName("");
    setNewType("Department");
    setNewDepartment(departments[0] ? String(departments[0].id) : "");
    setVisibility("private");
    setAutoAssign(true);
    setAutoAdmin(true);
  };

  const handleCreate = async () => {
    if (!newName.trim()) return;
    setCreating(true);
    try {
      await groupsApi.create({
        name: newName.trim(),
        type: newType,
        department: newDepartment || null,
        visibility,
        auto_assign: autoAssign,
        auto_admin: autoAdmin,
      });
      setShowCreate(false);
      resetCreateForm();
      await loadData();
    } catch (err) {
      console.error("Failed to create workspace:", err);
      setError("Couldn't create the workspace. Please try again.");
    } finally {
      setCreating(false);
    }
  };

  const handleDelete = async (id) => {
    setOpenMenu(null);
    try {
      await groupsApi.remove(id);
      setWorkspaces((prev) => prev.filter((w) => w.id !== id));
    } catch (err) {
      console.error("Failed to delete workspace:", err);
      setError("Couldn't delete the workspace. Please try again.");
    }
  };

  const totalBoards = workspaces.reduce((a, w) => a + (w.boards_count ?? 0), 0);
  const totalMembers = workspaces.reduce((a, w) => a + (w.members_count ?? 0), 0);
  const restrictedCount = workspaces.filter((w) => w.status === "restricted").length;

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64 text-[#555]">
        <Loader2 size={20} className="animate-spin mr-2" /> Loading workspaces…
      </div>
    );
  }

  return (
    <div className="space-y-5">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-xl font-bold text-white">Workspaces</h1>
          <p className="text-[#444] text-xs mt-0.5">Departmental and program-level containers for all work</p>
        </div>
        {canCreateWorkspace && (
  <button
    onClick={() => setShowCreate(true)}
    className="flex items-center gap-2 bg-[#F5C518] text-black px-4 py-2 rounded-xl text-sm font-semibold hover:bg-[#E6B800] transition-all"
  >
    <Plus size={15} />
    New Workspace
  </button>
)}
      </div>

      {error && (
        <div className="bg-red-500/10 border border-red-500/20 text-red-400 text-xs rounded-xl px-4 py-3 flex items-center justify-between">
          <span>{error}</span>
          <button onClick={loadData} className="underline hover:text-red-300">Retry</button>
        </div>
      )}

      {/* Stats */}
      <div className="grid grid-cols-4 gap-4">
        {[
          { label: "Total Workspaces", value: filtered.length, color: "#F5C518" },
          { label: "Total Boards", value: totalBoards, color: "#60A5FA" },
          { label: "Total Members", value: totalMembers, color: "#4ADE80" },
          { label: "Restricted", value: restrictedCount, color: "#FB923C" },
        ].map((s) => (
          <div key={s.label} className="bg-[#111111] border border-[#1E1E1E] rounded-2xl p-4">
            <div className="text-2xl font-bold mb-0.5" style={{ color: s.color }}>{s.value}</div>
            <div className="text-[#444] text-xs">{s.label}</div>
          </div>
        ))}
      </div>

      {/* Toolbar */}
      <div className="flex gap-3 items-center">
        <div className="relative flex-1 max-w-sm">
          <Search size={13} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#444]" />
          <input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search workspaces..."
            className="w-full bg-[#111111] border border-[#1E1E1E] text-white pl-9 pr-4 py-2 rounded-xl text-xs placeholder-[#333] focus:outline-none focus:border-[#F5C518]/40 transition-all"
          />
        </div>
        <div className="flex items-center bg-[#111111] border border-[#1E1E1E] rounded-xl overflow-hidden">
          <button onClick={() => setView("grid")} className={`p-2 transition-all ${view === "grid" ? "bg-[#F5C518]/10 text-[#F5C518]" : "text-[#444] hover:text-white"}`}>
            <LayoutGrid size={15} />
          </button>
          <button onClick={() => setView("list")} className={`p-2 transition-all ${view === "list" ? "bg-[#F5C518]/10 text-[#F5C518]" : "text-[#444] hover:text-white"}`}>
            <List size={15} />
          </button>
        </div>
      </div>

      {!filtered.length && (
        <div className="bg-[#111111] border border-[#1E1E1E] rounded-2xl p-10 text-center text-[#444] text-sm">
          No workspaces match your search.
        </div>
      )}

      {/* Grid view */}
      {view === "grid" && filtered.length > 0 && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {filtered.map((ws) => {
            const color = colorForDept(ws.department_id ?? ws.id ?? 0);
            return (
              <div key={ws.id} className="bg-[#111111] border border-[#1E1E1E] rounded-2xl p-5 hover:border-[#2A2A2A] transition-all group">
                <div className="flex items-start justify-between mb-4">
                  <div className="flex items-center gap-3">
                    <div className="w-9 h-9 rounded-xl flex items-center justify-center" style={{ background: `${color}20` }}>
                      <Layers size={16} style={{ color }} />
                    </div>
                    <div>
                      <div className="text-white text-sm font-semibold">{ws.name}</div>
                      <div className="text-[#444] text-[10px]">{ws.group_type}{ws.description ? ` · ${ws.description}` : ""}</div>
                    </div>
                  </div>
                  <div className="relative">
                    <button onClick={() => setOpenMenu(openMenu === ws.id ? null : ws.id)} className="opacity-0 group-hover:opacity-100 text-[#444] hover:text-white transition-all">
                      <MoreHorizontal size={15} />
                    </button>
                    {openMenu === ws.id && (
                      <div className="absolute right-0 top-6 z-20 bg-[#1A1A1A] border border-[#2A2A2A] rounded-xl p-1 w-40 shadow-xl">
                        <button onClick={() => setOpenMenu(null)} className="w-full flex items-center gap-2.5 px-3 py-2 rounded-lg text-xs hover:bg-[#2A2A2A] transition-all text-white">
                          <Eye size={13} /> View Workspace
                        </button>
                        <button onClick={() => setOpenMenu(null)} className="w-full flex items-center gap-2.5 px-3 py-2 rounded-lg text-xs hover:bg-[#2A2A2A] transition-all text-white">
                          <Settings size={13} /> Settings
                        </button>
                        <button onClick={() => handleDelete(ws.id)} className="w-full flex items-center gap-2.5 px-3 py-2 rounded-lg text-xs hover:bg-[#2A2A2A] transition-all text-red-400">
                          <Trash2 size={13} /> Delete
                        </button>
                      </div>
                    )}
                  </div>
                </div>

                <div className="flex items-center gap-3 mb-3 flex-wrap">
                  <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-[10px] border ${STATUS_STYLES[ws.status] ?? STATUS_STYLES.active}`}>
                    {ws.status ?? "active"}
                  </span>
                  <span className="inline-flex items-center gap-1 text-[10px] text-[#666]">
                    {ws.visibility === "private" ? <Lock size={10} /> : <ShieldCheck size={10} />}
                    {ws.visibility === "private" ? "Private" : "Public"}
                  </span>
                </div>

                <div className="flex items-center gap-4 mb-3 text-xs text-[#555]">
                  <div className="flex items-center gap-1"><Users size={11} /> {ws.members_count ?? 0} members</div>
                  <div className="flex items-center gap-1"><Layers size={11} /> {ws.boards_count ?? 0} boards</div>
                </div>

                <div className="flex items-center justify-between">

  <button
    onClick={() =>
      setExpanded(expanded === ws.id ? null : ws.id)
    }
    className="text-xs text-[#F5C518] hover:text-[#E6B800] transition-colors"
  >
    {expanded === ws.id
      ? "Hide boards ↑"
      : `View boards (${ws.boards_count ?? 0}) ↓`}
  </button>

  <button
    onClick={() => openWorkspace(ws)}
    className="px-4 py-2 rounded-lg bg-[#F5C518] text-black hover:bg-[#E6B800] transition-all"
  >
    Open Workspace
  </button>

</div>
                {expanded === ws.id && (
                  <div className="mt-3 space-y-1.5">
                    {(ws.boards ?? []).length === 0 && (
                      <div className="text-[10px] text-[#333]">No boards yet.</div>
                    )}
                    {(ws.boards ?? []).map((b) => (
                      <div key={b.id ?? b} className="flex items-center gap-2 text-xs text-[#888] bg-[#0D0D0D] rounded-lg px-3 py-1.5 border border-[#1A1A1A]">
                        <div className="w-1.5 h-1.5 rounded-full" style={{ background: color }} />
                        {b.name ?? b}
                      </div>
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* List view */}
      {view === "list" && filtered.length > 0 && (
        <div className="bg-[#111111] border border-[#1E1E1E] rounded-2xl overflow-hidden">
          <table className="w-full text-xs">
            <thead>
              <tr className="border-b border-[#1A1A1A]">
                {["Workspace", "Department", "Admin", "Members", "Boards", "Visibility", "Status", ""].map((h) => (
                  <th key={h} className="text-left text-[#444] font-medium px-4 py-3">{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {filtered.map((ws) => {
                const color = colorForDept(ws.department_id ?? ws.id ?? 0);
                return (
                  <tr key={ws.id} className="border-b border-[#0D0D0D] hover:bg-[#141414] transition-all group">
                    <td className="px-4 py-3">
                      <div className="flex items-center gap-3">
                        <div className="w-6 h-6 rounded-lg flex items-center justify-center" style={{ background: `${color}20` }}>
                          <Layers size={12} style={{ color }} />
                        </div>
                        <span className="text-white font-medium">{ws.name}</span>
                      </div>
                    </td>
                    <td className="px-4 py-3 text-[#888]">
  {ws.description ?? "—"}
</td>
                    <td className="px-4 py-3 text-[#888]">{ws.admin_name ?? "Unassigned"}</td>
                    <td className="px-4 py-3 text-[#888]">{ws.members_count ?? 0}</td>
                    <td className="px-4 py-3 text-[#888]">{ws.boards_count ?? 0}</td>
                    <td className="px-4 py-3 text-[#888] capitalize">{ws.visibility ?? "private"}</td>
                    <td className="px-4 py-3">
                      <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs border ${STATUS_STYLES[ws.status] ?? STATUS_STYLES.active}`}>
                        {ws.status ?? "active"}
                      </span>
                    </td>
                    <td className="px-4 py-3">
                      <button
                        onClick={() => handleDelete(ws.id)}
                        className="opacity-0 group-hover:opacity-100 text-[#444] hover:text-red-400 transition-all"
                      >
                        <MoreHorizontal size={14} />
                      </button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {/* Create modal */}
     {canCreateWorkspace && showCreate && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm">
          <div className="bg-[#111111] border border-[#2A2A2A] rounded-2xl p-6 w-full max-w-md mx-4 shadow-2xl">
            <h2 className="text-white font-semibold text-base mb-1">Create Workspace</h2>
            <p className="text-[#444] text-xs mb-5">Workspaces organise boards by department, program, or business unit.</p>

            <div className="space-y-4 max-h-[60vh] overflow-y-auto pr-1">
              <div>
                <label className="text-xs text-[#888] block mb-1.5">Workspace Name</label>
                <input
                  value={newName}
                  onChange={(e) => setNewName(e.target.value)}
                  placeholder="e.g. Marketing"
                  className="w-full bg-[#0D0D0D] border border-[#2A2A2A] text-white px-4 py-2.5 rounded-xl text-sm placeholder-[#333] focus:outline-none focus:border-[#F5C518]/50 transition-all"
                />
              </div>
     
              <div>
                <label className="text-xs text-[#888] block mb-1.5">Workspace Type</label>
                <select
                  value={newType}
                  onChange={(e) => setNewType(e.target.value)}
                  className="w-full bg-[#0D0D0D] border border-[#2A2A2A] text-white px-3 py-2.5 rounded-xl text-sm focus:outline-none focus:border-[#F5C518]/50 transition-all"
                >
                  {["Department", "Program", "Restricted", "Temporary"].map((t) => <option key={t}>{t}</option>)}
                </select>
              </div>

              <div>
                <label className="text-xs text-[#888] block mb-1.5">Department</label>
                <select
                  value={newDepartment}
                  onChange={(e) => setNewDepartment(e.target.value)}
                  className="w-full bg-[#0D0D0D] border border-[#2A2A2A] text-white px-3 py-2.5 rounded-xl text-sm focus:outline-none focus:border-[#F5C518]/50 transition-all"
                >
                  {departments.length === 0 && <option value="">No departments found</option>}
                  {departments.map((d) => (
                    <option key={d.id} value={d.id}>{d.name}</option>
                  ))}
                </select>
              </div>

              <div>
                <label className="text-xs text-[#888] block mb-1.5">Visibility</label>
                <div className="flex bg-[#0D0D0D] border border-[#2A2A2A] rounded-xl overflow-hidden">
                  {["private", "public"].map((v) => (
                    <button
                      key={v}
                      onClick={() => setVisibility(v)}
                      className={`flex-1 py-2 text-xs capitalize transition-all ${visibility === v ? "bg-[#F5C518]/10 text-[#F5C518]" : "text-[#666] hover:text-white"}`}
                    >
                      {v}
                    </button>
                  ))}
                </div>
              </div>

              <label className="flex items-center gap-2.5 text-xs text-[#888] cursor-pointer">
                <input type="checkbox" checked={autoAssign} onChange={(e) => setAutoAssign(e.target.checked)} className="accent-[#F5C518]" />
                Automatically add department members
              </label>

              <label className="flex items-center gap-2.5 text-xs text-[#888] cursor-pointer">
                <input type="checkbox" checked={autoAdmin} onChange={(e) => setAutoAdmin(e.target.checked)} className="accent-[#F5C518]" />
                Make Head of Department workspace admin
              </label>
            </div>

            <div className="flex gap-3 mt-6">
              <button
  onClick={handleCreate}
  disabled={creating || !newName.trim()}
  className="flex-1 bg-[#F5C518] text-black py-2.5 rounded-xl text-sm font-semibold hover:bg-[#E6B800] transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
>
  {creating && <Loader2 size={14} className="animate-spin" />}
  {creating ? "Creating…" : "Create"}
</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
